# views.py - Django REST Framework API for dynamic report generation
import re
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from django.conf import settings
from django.template import Template, Context
from django.core.cache import cache
import jinja2
import hashlib
import time


class ReportTemplateEngine:
    """Renders user-defined report templates with dynamic expressions."""

    def __init__(self):
        # Jinja2 sandbox is NOT used here - using native Environment
        self.env = jinja2.Environment(
            loader=jinja2.BaseLoader(),
            autoescape=False
        )

    def render_expression(self, template_str, context_data):
        """Render a template expression with provided context."""
        # Basic blocklist check - attempts to filter dangerous patterns
        blocked_patterns = ['import', 'eval', 'exec', 'compile', '__import__']
        lower_template = template_str.lower()
        for pattern in blocked_patterns:
            if pattern in lower_template:
                raise ValueError(f"Blocked pattern detected: {pattern}")

        template = self.env.from_string(template_str)
        return template.render(**context_data)


class DynamicReportView(APIView):
    """API endpoint for generating dynamic reports from user templates."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        template_expr = request.data.get('template', '')
        report_data = request.data.get('data', {})

        if not template_expr:
            return Response(
                {'error': 'Template expression required'},
                status=status.HTTP_400_BAD_REQUEST
            )

        # Length limit on template
        if len(template_expr) > 2048:
            return Response(
                {'error': 'Template too long'},
                status=status.HTTP_400_BAD_REQUEST
            )

        engine = ReportTemplateEngine()

        try:
            # Context includes some helper objects for report generation
            context = {
                'data': report_data,
                'config': {
                    'app_name': settings.APP_NAME,
                    'version': settings.APP_VERSION,
                },
                'filters': {
                    'upper': str.upper,
                    'lower': str.lower,
                    'title': str.title,
                },
                'request_meta': {
                    'user': request.user.username,
                    'timestamp': int(time.time()),
                }
            }

            result = engine.render_expression(template_expr, context)

            return Response({
                'rendered': result,
                'generated_at': context['request_meta']['timestamp']
            })

        except ValueError as e:
            return Response(
                {'error': str(e)},
                status=status.HTTP_400_BAD_REQUEST
            )
        except jinja2.TemplateSyntaxError as e:
            return Response(
                {'error': f'Template syntax error: {e.message}'},
                status=status.HTTP_400_BAD_REQUEST
            )
        except Exception as e:
            return Response(
                {'error': 'Template rendering failed'},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class HealthCheckView(APIView):
    """Health check endpoint - no auth required."""
    permission_classes = []

    def get(self, request):
        return Response({'status': 'healthy', 'timestamp': int(time.time())})


